<?php require 'config.php';header_html('Giỏ hàng');$cart=$_SESSION['cart']??[];$total=0;?><h1 class="fw-bold mb-4">Giỏ hàng</h1><?php if(!$cart):?><div class="empty-state"><i class="fa-solid fa-basket-shopping"></i><h4>Giỏ hàng đang trống</h4><a class="btn btn-primary mt-3" href="index.php">Khám phá giáo trình</a></div><?php else:?><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Giáo trình</th><th>Đơn giá</th><th>Số lượng</th><th>Tạm tính</th><th></th></tr></thead><tbody><?php foreach($cart as $it):$sub=$it['price']*$it['quantity'];$total+=$sub;?><tr><td class="fw-semibold"><?=e($it['title'])?></td><td><?=money($it['price'])?></td><td><form class="d-flex gap-2" method="post" action="cart_action.php"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="update"><input type="hidden" name="book_id" value="<?=$it['id']?>"><input class="form-control form-control-sm" style="width:75px" type="number" min="1" max="99" name="quantity" value="<?=$it['quantity']?>"><button class="btn btn-sm btn-outline-primary">Cập nhật</button></form></td><td class="fw-bold"><?=money($sub)?></td><td><form method="post" action="cart_action.php"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="book_id" value="<?=$it['id']?>"><button class="btn btn-sm btn-outline-danger"><i class="fa fa-trash"></i></button></form></td></tr><?php endforeach;?></tbody></table></div></div><div class="d-flex justify-content-between align-items-center mt-4 flex-wrap gap-3"><form method="post" action="cart_action.php"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="clear"><button class="btn btn-outline-danger">Xóa giỏ hàng</button></form><div class="text-end"><h4>Tổng cộng: <span class="price"><?=money($total)?></span></h4><a href="checkout.php" class="btn btn-success btn-lg">Tiến hành đặt hàng</a></div></div><?php endif;?><?php footer_html();?>
